questionvariables.text:
cosd(x) := cos(x*%pi/180);
sind(x) := sin(x*%pi/180);
atand(x) := 180*atan(x)/%pi;
asind(x) := 180*asin(x)/%pi;
two(v) := if v < 10 then sconcat("0", string(v)) else string(v);
hm(m) := block([q], q: mod(m, 1440), sconcat(two(floor(q/60)), ":", two(mod(q, 60))));
dmx(m) := sconcat(string(floor(m/60)), "^\\circ", two(mod(m, 60)), "'");
/* Design: differences of latitude and longitude. Entry: [A, deg, min, N/S, deg, min, E/W, B, ...]; sw swaps the order. Angles in minutes. The long-way node (21600 - okB) applies on every entry; the borrow nodes only where the minutes do not subtract (elsewhere borA = -1, borB = -2: values no answer in degrees and minutes reaches, used only by the borrow test). Source: adapted from SMP Book 5 (Metric), chapter 3, Exercise C question 8 and Exercise D question 4. */
L: [["Nairobi",1,17,"S",36,49,"E","Mandera",3,56,"N",41,52,"E"],["Mombasa",4,3,"S",39,40,"E","Dar es Salaam",6,48,"S",39,17,"E"],["Kisumu",0,6,"S",34,45,"E","Accra",5,33,"N",0,12,"W"],["Addis Ababa",9,2,"N",38,45,"E","Mumbai",19,5,"N",72,53,"E"],["Nairobi",1,17,"S",36,49,"E","Honolulu",21,18,"N",157,51,"W"],["Mombasa",4,3,"S",39,40,"E","Rio de Janeiro",22,54,"S",43,10,"W"],["Addis Ababa",9,2,"N",38,45,"E","Mogadishu",2,3,"N",45,19,"E"],["Dar es Salaam",6,48,"S",39,17,"E","Lima",12,3,"S",77,3,"W"],["Lodwar",3,7,"N",35,36,"E","Perth",31,57,"S",115,51,"E"],["Mombasa",4,3,"S",39,40,"E","Honolulu",21,18,"N",157,51,"W"]];
ix: 1+rand(10);
sw: rand(2);
E: L[ix];
P1: makelist(E[j],j,1,7); P2: makelist(E[j],j,8,14);
PA: if sw=0 then P1 else P2; PB: if sw=0 then P2 else P1;
dA: PA[2]; mA: PA[3]; nsA: PA[4]; gdA: PA[5]; gmA: PA[6]; ewA: PA[7];
dB: PB[2]; mB: PB[3]; nsB: PB[4]; gdB: PB[5]; gmB: PB[6]; ewB: PB[7];
la: 60*dA+mA; lb: 60*dB+mB; ga: 60*gdA+gmA; gb: 60*gdB+gmB;
sameL: is(nsA=nsB); sameG: is(ewA=ewB);
okA: if sameL then abs(la-lb) else la+lb;
wrA: if sameL then la+lb else abs(la-lb);
hbA: sameL and is((dA-dB)*(mA-mB)<0);
borA: if hbA then 60*abs(dA-dB)+abs(mA-mB) else -1;
sG: ga+gb;
ovr: is(not sameG and sG>10800);
okB: if sameG then abs(ga-gb) else (if sG>10800 then 21600-sG else sG);
wrB: if sameG then ga+gb else abs(ga-gb);
ovB: 21600-okB;
hbB: sameG and is((gdA-gdB)*(gmA-gmB)<0);
borB: if hbB then 60*abs(gdA-gdB)+abs(gmA-gmB) else -2;
hiA: max(la,lb); loA: min(la,lb); hiB: max(ga,gb); loB: min(ga,gb);

feedbackvariables.text:
TA: 60*ans1+ans2;
c1: is(TA=okA and ans2<60 and ans2>=0);
f1: is(TA=okA);
r1: is(TA=wrA);
b1: is(TA=borA);
yk1: if sameL then is(TA>=0) else is(TA>=la);

TB: 60*ans3+ans4;
c2: is(TB=okB and ans4<60 and ans4>=0);
f2: is(TB=okB);
o2: is(TB=ovB);
r2: is(TB=wrB);
b2: is(TB=borB);
yk2: if sameG then is(TB>=0) else (if ovr then is(TB>=0) else is(TB>=ga));
